import {
  DriverError,
  diffKeyEntries,
  generateKeyName,
  type DatabaseSpec,
  type DdlStatement,
  type ForeignKeySpec,
  type TableSpec,
} from '@db-explorer/core';
import { quoteOracleIdentifier } from './sql';

/**
 * Oracle 表结构编辑 / 库级 DDL 语句生成（M8-Oracle，概要 §5.9 / §5.10 / ADR D-23）：
 * - DDL 不可参数化（驱动规范 §10）：标识符 fail-closed（双引号字符与控制字符拒绝，P-58 口径）
 *   + 双引号引用（"" 翻倍转义）；字面量 '' 转义
 * - 契约 fixture 用通用类型（bigint/varchar(n)…）→ 翻译层映射 Oracle 原生类型（INT/INTEGER/
 *   VARCHAR 是 ANSI 别名可直发，BIGINT 不是——统一翻译保证 roundtrip 稳定）；词表外类型原样透传
 * - 自增 = GENERATED BY DEFAULT AS IDENTITY（12c+）；ALTER 原地增删 IDENTITY 不支持 →
 *   E_UNSUPPORTED（README 声明；主键变更不触达 identity 属性，无需中止）
 * - UNIQUE 走具名 CONSTRAINT（隐式唯一索引同名）；FK 删除必须按约束名（Oracle 无 DROP FOREIGN
 *   KEY 语法）；UK 删除走 DROP CONSTRAINT（名来自基线回读）；主键 DROP PRIMARY KEY（无需名）
 * - 注释为方言原生 COMMENT ON（表/列），删除语义 = IS NULL
 * - 空串=NULL 引擎语义（ADR D-23 岔口 4）：默认值字面量 '' 拒绝（E_VALIDATION，改用 NULL）
 * 纯函数，有单测。
 */

/** 标识符校验（危险字符黑名单，P-58）：只拒绝方言引号字符（双引号，防逃逸）与控制字符；
 *  连字符/点/空格/中文等真实合法名交由 quoteOracleIdentifier 双写转义承载 */
// eslint-disable-next-line no-control-regex -- 刻意匹配控制字符：拒绝它们正是本校验的职责（escapeDdlLiteral 同款豁免）
const IDENT_DANGEROUS_RE = /[\u0000-\u001F\u007F"]/;

function assertIdentifier(kind: string, name: string): string {
  if (!name || name.length > 128 || IDENT_DANGEROUS_RE.test(name)) {
    throw new DriverError('E_VALIDATION', `${kind} "${name}" 含非法字符（方言引号字符与控制字符不允许）`);
  }
  return name;
}

/** 字面量转义：数值/函数/日期关键字原样；其余 '' 字符串字面量（'' 翻倍）；空串 → E_VALIDATION
 *  （Oracle 空串即 NULL，默认值/注释语义用 NULL 明示）；控制字符拒绝 */
export function escapeDdlLiteral(value: string): string {
  const t = value.trim();
  if (
    /^-?\d+(\.\d+)?$/.test(t) ||
    /^(SYSDATE|SYSTIMESTAMP|CURRENT_TIMESTAMP|CURRENT_DATE|LOCALTIMESTAMP)$/i.test(t) ||
    /^[a-z_][a-z0-9_]*\s*\(/i.test(t)
  ) {
    return t;
  }
  // eslint-disable-next-line no-control-regex -- 刻意拒绝控制字符（驱动规范 §10 fail-closed）
  if (/[\r\n\x00]/.test(value)) {
    throw new DriverError('E_VALIDATION', '默认值不允许包含换行或控制字符');
  }
  if (value === '') {
    throw new DriverError('E_VALIDATION', 'Oracle 空串即 NULL：默认值请留空（无默认）或显式使用 NULL');
  }
  return `'${value.replace(/'/g, "''")}'`;
}

/**
 * 契约/编辑器通用类型 → Oracle 原生类型（仅命中别名时翻译，其余原样透传）。
 * Oracle 接受 INT/INTEGER/VARCHAR 等 ANSI 别名但 BIGINT 不是合法类型——统一翻译保证
 * roundtrip 稳定（VARCHAR 别名在存储层折叠为 VARCHAR2）。
 */
export function translateOracleType(dataType: string): string {
  const t = dataType.trim();
  const bare = t.replace(/\s+/g, ' ').toLowerCase();
  if (bare === 'bigint' || bare === 'int8') return 'NUMBER(19, 0)';
  if (bare === 'int' || bare === 'integer') return 'NUMBER(10, 0)';
  if (bare === 'smallint') return 'NUMBER(5, 0)';
  if (bare === 'tinyint') return 'NUMBER(3, 0)';
  if (bare === 'boolean' || bare === 'bool') return 'NUMBER(1, 0)'; // Oracle ≤22 无 BOOLEAN 列（23ai 起有）
  if (bare === 'text') return 'CLOB';
  let m = /^(?:decimal|numeric)(?:\(\s*(\d+)\s*(?:,\s*(\d+)\s*)?\))?$/.exec(bare);
  if (m) {
    return m[1] === undefined ? 'NUMBER' : m[2] === undefined ? `NUMBER(${m[1]}, 0)` : `NUMBER(${m[1]}, ${m[2]})`;
  }
  m = /^varchar2?\(\s*(\d+)\s*\)$/.exec(bare);
  if (m) return `VARCHAR2(${m[1]} CHAR)`;
  m = /^nvarchar\(\s*(\d+)\s*\)$/.exec(bare);
  if (m) return `NVARCHAR2(${m[1]})`;
  m = /^char\(\s*(\d+)\s*\)$/.exec(bare);
  if (m) return `CHAR(${m[1]} CHAR)`;
  return t;
}

/** 类型比较归一（大小写折叠 + 空白归一）：Oracle 存储形态恒大写，编辑器输入大小写自由——
 *  不归一则 'varchar2(64)' vs 'VARCHAR2(64)' 产生假 ALTER */
function sameDataType(a: string, b: string): boolean {
  return a.replace(/\s+/g, ' ').trim().toUpperCase() === b.replace(/\s+/g, ' ').trim().toUpperCase();
}

/** 列定义片段："name" TYPE [GENERATED BY DEFAULT AS IDENTITY] [DEFAULT …] [NOT NULL|NULL]
 *  （Oracle 语法序：DEFAULT 必须先于 NULL/NOT NULL 内联约束——顺序颠倒报 ORA-00907） */
function columnDefSql(col: TableSpec['columns'][number]): string {
  const parts = [
    quoteOracleIdentifier(assertIdentifier('列名', col.name)),
    translateOracleType(col.dataType),
  ];
  if (col.autoIncrement) {
    parts.push('GENERATED BY DEFAULT AS IDENTITY');
  }
  if (col.defaultValue !== undefined && col.defaultValue !== '') {
    parts.push(`DEFAULT ${escapeDdlLiteral(col.defaultValue)}`);
  }
  parts.push(col.nullable ? 'NULL' : 'NOT NULL');
  return parts.join(' ');
}

/** 注释文本转义（COMMENT ON 字面量；控制字符拒绝） */
function escapeComment(value: string): string {
  // eslint-disable-next-line no-control-regex -- 刻意拒绝控制字符（驱动规范 §10 fail-closed）
  if (/[\x00]/.test(value)) {
    throw new DriverError('E_VALIDATION', '注释不允许包含控制字符');
  }
  return `'${value.replace(/'/g, "''")}'`;
}

/** 列名清单字面量（键/外键/索引共用） */
function columnListLit(columns: readonly string[]): string {
  if (columns.length === 0) {
    throw new DriverError('E_VALIDATION', '键/索引至少需要一列');
  }
  return columns.map((c) => quoteOracleIdentifier(assertIdentifier('列名', c))).join(', ');
}

/** Oracle 外键动作后缀：ON DELETE 仅 CASCADE/SET NULL（NO ACTION = Oracle 默认省略）；
 *  ON UPDATE 无对应语法 → E_VALIDATION（交互稿 §14.4：refActions 声明裁剪的驱动侧兜底） */
function oracleForeignKeyActionSuffix(fk: ForeignKeySpec): string {
  if (fk.onUpdate) {
    throw new DriverError('E_VALIDATION', 'Oracle 不支持 ON UPDATE 动作');
  }
  if (!fk.onDelete || fk.onDelete === 'NO ACTION') {
    return '';
  }
  if (fk.onDelete !== 'CASCADE' && fk.onDelete !== 'SET NULL') {
    throw new DriverError('E_VALIDATION', `Oracle 外键 ON DELETE 仅支持 CASCADE/SET NULL，收到 ${fk.onDelete}`);
  }
  return ` ON DELETE ${fk.onDelete}`;
}

/** 唯一键/外键的 CREATE TABLE 内联 CONSTRAINT 子句（索引走独立 CREATE INDEX） */
function appendCreateConstraintClauses(cols: string[], spec: TableSpec): void {
  const taken = new Set<string>();
  for (const k of [...(spec.uniqueKeys ?? []), ...(spec.foreignKeys ?? [])]) {
    if (k.name) {
      taken.add(k.name);
    }
  }
  for (const uk of spec.uniqueKeys ?? []) {
    const name = assertIdentifier('唯一键名', uk.name ?? generateKeyName('uk', spec.name, taken));
    taken.add(name);
    cols.push(`CONSTRAINT ${quoteOracleIdentifier(name)} UNIQUE (${columnListLit(uk.columns)})`);
  }
  for (const fk of spec.foreignKeys ?? []) {
    if (fk.refColumns.length !== fk.columns.length) {
      throw new DriverError('E_VALIDATION', `外键 "${fk.name ?? '(未命名)'}" 引用列数须与本地列数一致`);
    }
    const name = assertIdentifier('外键名', fk.name ?? generateKeyName('fk', spec.name, taken));
    taken.add(name);
    cols.push(
      `CONSTRAINT ${quoteOracleIdentifier(name)} FOREIGN KEY (${columnListLit(fk.columns)}) REFERENCES ${quoteOracleIdentifier(assertIdentifier('引用表名', fk.refTable))} (${columnListLit(fk.refColumns)})${oracleForeignKeyActionSuffix(fk)}`,
    );
  }
}

/** 二级索引独立语句（CREATE [UNIQUE] INDEX；索引类型 BITMAP 单列传递） */
function createIndexStatements(db: string, spec: TableSpec): DdlStatement[] {
  const taken = new Set((spec.uniqueKeys ?? []).map((k) => k.name).filter(Boolean) as string[]);
  const qualified = `${quoteOracleIdentifier(db)}.${quoteOracleIdentifier(spec.name)}`;
  return (spec.indexes ?? []).map((idx) => {
    const name = assertIdentifier('索引名', idx.name ?? generateKeyName('idx', spec.name, taken));
    taken.add(name);
    const bitmap = idx.type?.trim().toUpperCase() === 'BITMAP' ? 'BITMAP ' : '';
    return {
      sql: `CREATE ${idx.unique ? 'UNIQUE ' : ''}${bitmap}INDEX ${quoteOracleIdentifier(name)} ON ${qualified} (${columnListLit(idx.columns)})`,
    };
  });
}

/** 注释语句（COMMENT ON 表/列；Oracle 方言原生） */
export function buildCommentStatements(db: string, spec: TableSpec): DdlStatement[] {
  const qualified = `${quoteOracleIdentifier(db)}.${quoteOracleIdentifier(assertIdentifier('表名', spec.name))}`;
  const statements: DdlStatement[] = [];
  if (spec.comment) {
    statements.push({ sql: `COMMENT ON TABLE ${qualified} IS ${escapeComment(spec.comment)}` });
  }
  for (const c of spec.columns) {
    if (c.comment) {
      statements.push({
        sql: `COMMENT ON COLUMN ${qualified}.${quoteOracleIdentifier(assertIdentifier('列名', c.name))} IS ${escapeComment(c.comment)}`,
      });
    }
  }
  return statements;
}

export function buildCreateTableStatements(db: string, spec: TableSpec): DdlStatement[] {
  assertIdentifier('schema 名', db);
  assertIdentifier('表名', spec.name);
  if (spec.columns.length === 0) {
    throw new DriverError('E_VALIDATION', '表至少需要一列');
  }
  const identities = spec.columns.filter((c) => c.autoIncrement);
  if (identities.length > 1) {
    throw new DriverError('E_VALIDATION', '一张表只允许一个自增列（Oracle IDENTITY 约束）');
  }
  for (const c of spec.columns) {
    if (c.autoIncrement && !c.isPrimaryKey) {
      throw new DriverError('E_VALIDATION', `列 "${c.name}" 声明了自增但不是主键`);
    }
  }
  const cols = spec.columns.map(columnDefSql);
  const pk = spec.columns.filter((c) => c.isPrimaryKey).map((c) => quoteOracleIdentifier(c.name));
  if (pk.length > 0) {
    cols.push(`PRIMARY KEY (${pk.join(', ')})`);
  }
  appendCreateConstraintClauses(cols, spec);
  const statements: DdlStatement[] = [
    { sql: `CREATE TABLE ${quoteOracleIdentifier(db)}.${quoteOracleIdentifier(spec.name)} (\n  ${cols.join(',\n  ')}\n)` },
    ...createIndexStatements(db, spec),
    ...buildCommentStatements(db, spec),
  ];
  return statements;
}

export function buildAlterTableStatements(
  db: string,
  obj: string,
  spec: TableSpec,
  current: TableSpec,
): DdlStatement[] {
  assertIdentifier('schema 名', db);
  assertIdentifier('表名', spec.name);
  assertIdentifier('表名', obj);
  for (const c of spec.columns) {
    assertIdentifier('列名', c.name);
    if (c.autoIncrement && !c.isPrimaryKey) {
      throw new DriverError('E_VALIDATION', `列 "${c.name}" 声明了自增但不是主键`);
    }
  }
  const statements: DdlStatement[] = [];
  const alterPrefix = `${quoteOracleIdentifier(db)}.${quoteOracleIdentifier(spec.name)}`;

  // 重命名（后续语句引用新名）
  if (spec.name !== obj) {
    statements.push({ sql: `ALTER TABLE ${quoteOracleIdentifier(db)}.${quoteOracleIdentifier(obj)} RENAME TO ${quoteOracleIdentifier(spec.name)}` });
  }

  const curByName = new Map(current.columns.map((c) => [c.name, c]));
  const tgtByName = new Map(spec.columns.map((c) => [c.name, c]));

  const curPk = current.columns.filter((c) => c.isPrimaryKey).map((c) => c.name);
  const tgtPk = spec.columns.filter((c) => c.isPrimaryKey).map((c) => c.name);
  const pkChanged = curPk.join(',') !== tgtPk.join(',');

  for (const c of spec.columns) {
    const cur = curByName.get(c.name);
    if (cur && Boolean(c.autoIncrement) !== Boolean(cur.autoIncrement)) {
      // IDENTITY 原地增删不支持（需重建表，README 已知限制）；主键变更不触达 identity 属性
      throw new DriverError('E_UNSUPPORTED', `列 "${c.name}" 的自增（IDENTITY）不支持原地变更，需要重建表`);
    }
  }

  const droppedCols = current.columns.filter((c) => !tgtByName.has(c.name));
  const alteredCols = spec.columns.filter((c) => {
    const cur = curByName.get(c.name);
    return cur && (!sameDataType(cur.dataType, c.dataType) || cur.nullable !== c.nullable);
  });
  const defaultChangedCols = spec.columns.filter((c) => {
    const cur = curByName.get(c.name);
    return cur && (cur.defaultValue ?? '') !== (c.defaultValue ?? '');
  });

  // ① 主键先删（无依赖 FK 时安全；DROP PRIMARY KEY 无需约束名——Oracle 方言语法）
  if (pkChanged && curPk.length > 0) {
    statements.push({ sql: `ALTER TABLE ${alterPrefix} DROP PRIMARY KEY`, destructive: true });
  }

  // ② 键/外键/索引 diff 删除半段（§12.7 红线：DROP 只由「基线存在且 spec 移除」生成）——
  //   必须在删列之前：Oracle 对被约束/索引依赖的列拒绝 DROP COLUMN
  const keyTaken = new Set<string>();
  for (const k of [...(current.uniqueKeys ?? []), ...(current.foreignKeys ?? []), ...(current.indexes ?? [])]) {
    if (k.name) {
      keyTaken.add(k.name);
    }
  }
  const ukDiff = diffKeyEntries(spec.uniqueKeys, current.uniqueKeys);
  const fkDiff = diffKeyEntries<ForeignKeySpec>(spec.foreignKeys, current.foreignKeys);
  const idxDiff = diffKeyEntries(spec.indexes, current.indexes);
  for (const k of [...fkDiff.dropped, ...fkDiff.changed]) {
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} DROP CONSTRAINT ${quoteOracleIdentifier(assertIdentifier('外键名', k.name!))}`,
    });
  }
  for (const k of [...ukDiff.dropped, ...ukDiff.changed]) {
    // UK 删除走约束名（基线回读携带；Oracle 具名 UNIQUE 的隐式索引随之删除）
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} DROP CONSTRAINT ${quoteOracleIdentifier(assertIdentifier('唯一键名', k.name!))}`,
    });
  }
  for (const k of [...idxDiff.dropped, ...idxDiff.changed]) {
    statements.push({ sql: `DROP INDEX ${quoteOracleIdentifier(assertIdentifier('索引名', k.name!))}` });
  }

  // ③ 删列（可能丢数据 → destructive；多列合并单句 DROP (a, b)）
  if (droppedCols.length > 0) {
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} DROP (${droppedCols.map((c) => quoteOracleIdentifier(c.name)).join(', ')})`,
      destructive: true,
    });
  }

  // ④ 改列（MODIFY 合并类型/默认值/可空——DEFAULT 先于 NOT NULL 的 Oracle 语法序；类型变化标 destructive）
  for (const tgt of alteredCols) {
    const parts = [quoteOracleIdentifier(tgt.name), translateOracleType(tgt.dataType)];
    if (tgt.defaultValue !== undefined && tgt.defaultValue !== '') {
      parts.push(`DEFAULT ${escapeDdlLiteral(tgt.defaultValue)}`);
    }
    parts.push(tgt.nullable ? 'NULL' : 'NOT NULL');
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} MODIFY (${parts.join(' ')})`,
      destructive: !sameDataType(curByName.get(tgt.name)!.dataType, tgt.dataType) || undefined,
    });
  }
  // ④′ 仅默认值变化（类型/可空未变）：清空默认值用 DEFAULT NULL（Oracle 无 DROP DEFAULT 语法）
  for (const tgt of defaultChangedCols) {
    if (alteredCols.includes(tgt)) continue;
    const value = tgt.defaultValue !== undefined && tgt.defaultValue !== '' ? ` DEFAULT ${escapeDdlLiteral(tgt.defaultValue)}` : ' DEFAULT NULL';
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} MODIFY (${quoteOracleIdentifier(tgt.name)}${value})`,
    });
  }

  // ⑤ 加列（行数据不丢 → 非 destructive；多列合并单句 ADD (a, b)）
  const addedCols = spec.columns.filter((c) => !curByName.has(c.name));
  if (addedCols.length > 0) {
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} ADD (${addedCols.map(columnDefSql).join(', ')})`,
    });
  }

  // ⑥ 主键重建（旧约束已在上文删除）
  if (pkChanged && tgtPk.length > 0) {
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} ADD PRIMARY KEY (${tgtPk.map((n) => quoteOracleIdentifier(n)).join(', ')})`,
    });
  }

  // ⑦ 键/外键/索引 diff 添加半段（列变更之后：外键/索引可引用新加列）
  for (const k of [...ukDiff.added, ...ukDiff.changed]) {
    const name = assertIdentifier('唯一键名', k.name ?? generateKeyName('uk', spec.name, keyTaken));
    keyTaken.add(name);
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} ADD CONSTRAINT ${quoteOracleIdentifier(name)} UNIQUE (${columnListLit(k.columns)})`,
    });
  }
  for (const k of [...fkDiff.added, ...fkDiff.changed]) {
    if (k.refColumns.length !== k.columns.length) {
      throw new DriverError('E_VALIDATION', `外键 "${k.name ?? '(未命名)'}" 引用列数须与本地列数一致`);
    }
    const name = assertIdentifier('外键名', k.name ?? generateKeyName('fk', spec.name, keyTaken));
    keyTaken.add(name);
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} ADD CONSTRAINT ${quoteOracleIdentifier(name)} FOREIGN KEY (${columnListLit(k.columns)}) REFERENCES ${quoteOracleIdentifier(assertIdentifier('引用表名', k.refTable))} (${columnListLit(k.refColumns)})${oracleForeignKeyActionSuffix(k)}`,
    });
  }
  for (const k of [...idxDiff.added, ...idxDiff.changed]) {
    const name = assertIdentifier('索引名', k.name ?? generateKeyName('idx', spec.name, keyTaken));
    keyTaken.add(name);
    const bitmap = k.type?.trim().toUpperCase() === 'BITMAP' ? 'BITMAP ' : '';
    statements.push({
      sql: `CREATE ${k.unique ? 'UNIQUE ' : ''}${bitmap}INDEX ${quoteOracleIdentifier(name)} ON ${alterPrefix} (${columnListLit(k.columns)})`,
    });
  }

  // ⑧ 表/列注释（COMMENT ON 既有语义 = 覆盖；删除 = IS NULL）
  if ((spec.comment ?? '') !== (current.comment ?? '')) {
    const qualified = `${quoteOracleIdentifier(db)}.${quoteOracleIdentifier(spec.name)}`;
    statements.push({
      sql: spec.comment
        ? `COMMENT ON TABLE ${qualified} IS ${escapeComment(spec.comment)}`
        : `COMMENT ON TABLE ${qualified} IS NULL`,
    });
  }
  for (const tgt of spec.columns) {
    const cur = curByName.get(tgt.name);
    if (cur && (cur.comment ?? '') !== (tgt.comment ?? '')) {
      const qualified = `${quoteOracleIdentifier(db)}.${quoteOracleIdentifier(spec.name)}.${quoteOracleIdentifier(tgt.name)}`;
      statements.push({
        sql: tgt.comment
          ? `COMMENT ON COLUMN ${qualified} IS ${escapeComment(tgt.comment)}`
          : `COMMENT ON COLUMN ${qualified} IS NULL`,
      });
    }
  }

  return statements;
}

// ── 库级 DDL（M8-DBDDL / D-19 / ADR D-23 岔口 8）：Oracle「库」= schema = 用户——
//    CREATE USER（需密码 + USERS 表空间配额）/ DROP USER … CASCADE（destructive）。
//    ALTER 不实现：Oracle 用户不可重命名（「编辑库」菜单按方法存在性裁剪）。

/** 标识符校验（黑名单，P-58 口径，同 assertIdentifier；密码额外拒绝双引号——quoted 密码字面量） */
// eslint-disable-next-line no-control-regex -- 刻意匹配控制字符：拒绝它们正是本校验的职责（IDENT_DANGEROUS_RE 同款豁免）
const PASSWORD_DANGEROUS_RE = /[\u0000-\u001F\u007F"]/;

function assertUserPassword(name: string, password: string | undefined): string {
  const pwd = password ?? '';
  if (!pwd || pwd.length > 128 || PASSWORD_DANGEROUS_RE.test(pwd)) {
    throw new DriverError('E_VALIDATION', `创建 schema "${name}" 需要提供密码（不允许引号与控制字符）`);
  }
  return pwd;
}

export function buildCreateUserStatements(spec: DatabaseSpec): DdlStatement[] {
  assertIdentifier('schema 名', spec.name);
  const pwd = assertUserPassword(spec.name, spec.password);
  return [
    {
      sql: `CREATE USER ${quoteOracleIdentifier(spec.name)} IDENTIFIED BY "${pwd}" DEFAULT TABLESPACE USERS QUOTA UNLIMITED ON USERS`,
    },
    // schema 可用性最小授权（建会话 + 建对象 + 视图；19c RESOURCE 不含 CREATE VIEW，实测 ORA-01031）
    { sql: `GRANT CREATE SESSION, RESOURCE, CREATE VIEW TO ${quoteOracleIdentifier(spec.name)}` },
  ];
}

export function buildDropUserStatements(db: string): DdlStatement[] {
  assertIdentifier('schema 名', db);
  return [{ sql: `DROP USER ${quoteOracleIdentifier(db)} CASCADE`, destructive: true }];
}
